// ENG-2228 text-shape links: meta.url storage + canvas overlay affordance.
// Harness contract: evaluate() bodies must start with an explicit `return`,
// waitFor() only succeeds on a literal true, key() takes an options object.
const CANVAS_CMD = "create-discourse-graph-canvas";
const ICON = ".tl-hyperlink-button";

const VIEW = `app.workspace.getLeavesOfType("tldraw-dg-preview")[0].view`;
const TEXT_SHAPES = `${VIEW}.store.allRecords().filter((r) => r.typeName === "shape" && r.type === "text")`;

const openCanvas = async ({ client, json, vault }) => {
  await client.evaluate(
    `return app.commands.executeCommandById(${json(`${vault.pluginId}:${CANVAS_CMD}`)});`,
  );
  await client.waitFor(`return !!document.querySelector(".tl-canvas");`, {
    label: "canvas mounted",
    timeout: 15000,
  });
  return client.evaluate(`return ${VIEW}.file.path;`);
};

const canvasPoint = ({ client }, dx = 0, dy = 0) =>
  client.evaluate(`const r = document.querySelector(".tl-canvas").getBoundingClientRect();
    return { x: Math.round(r.left + r.width / 2 + ${dx}), y: Math.round(r.top + r.height / 2 + ${dy}) };`);

const clickAt = async ({ client }, { x, y }, modifiers = 0, button = "left") => {
  for (const type of ["mousePressed", "mouseReleased"]) {
    await client.send("Input.dispatchMouseEvent", {
      type, x, y, button, clickCount: 1, modifiers,
      buttons: type === "mousePressed" ? (button === "right" ? 2 : 1) : 0,
    });
  }
};

// A text shape made the way a user makes one: text tool, click, type, Escape.
const createTextShapeViaToolbar = async (ctx, text) => {
  const { client } = ctx;
  const point = await canvasPoint(ctx);
  await clickAt(ctx, point);
  await client.key({ text: "t", key: "t", code: "KeyT", windowsVirtualKeyCode: 84, nativeVirtualKeyCode: 84 });
  await clickAt(ctx, point);
  await client.typeText(text);
  await client.pressEscape();
  await client.waitFor(`return ${TEXT_SHAPES}.length > 0;`, {
    label: "text shape in store",
    timeout: 10000,
  });
  return client.evaluate(`const t = ${TEXT_SHAPES}; const s = t[t.length - 1];
    return { id: s.id, metaKeys: Object.keys(s.meta), propKeys: Object.keys(s.props).sort() };`);
};

const setLinkOnShape = ({ client, json }, shapeId, url) =>
  client.evaluate(`const v = ${VIEW}; const s = v.store.get(${json(shapeId)});
    v.store.put([{ ...s, meta: { ...s.meta, url: ${json(url)} } }]);
    return true;`);

export default [
  {
    name: "Toolbar text shape is untouched stock",
    input: "text tool, click canvas, type 'linked note', Escape",
    expected: "text shape with no url in props and empty meta — stock schema, no migration needed",
    run: async (ctx) => {
      await openCanvas(ctx);
      return createTextShapeViaToolbar(ctx, "linked note");
    },
    expect: (actual) => ({
      pass: !!actual && !actual.propKeys.includes("url") && actual.metaKeys.length === 0,
      actual: `props=[${actual?.propKeys}] meta=[${actual?.metaKeys}]`,
    }),
  },
  {
    name: "Edit link appears for a text shape",
    input: "select the text shape, right-click, open the Edit submenu",
    expected: "'Edit link' listed — the patched gate accepts meta-based links",
    run: async (ctx) => {
      const { client } = ctx;
      await openCanvas(ctx);
      await createTextShapeViaToolbar(ctx, "linked note");
      const pos = await client.evaluate(`const el = document.querySelector('.tl-shape[data-shape-type="text"]');
        const r = el.getBoundingClientRect();
        return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };`);
      await clickAt(ctx, pos);
      await clickAt(ctx, pos, 0, "right");
      await client.waitFor(`return !!document.querySelector('[role="menuitem"]');`, { label: "context menu" });
      await client.evaluate(`const t = [...document.querySelectorAll('[role="menuitem"]')]
          .find((e) => e.textContent.trim() === "Edit");
        if (t) t.click();
        return !!t;`);
      await new Promise((r) => setTimeout(r, 500));
      return client.evaluate(`return [...document.querySelectorAll('[role="menuitem"], button')]
        .some((e) => e.textContent.trim().toLowerCase() === "edit link");`);
    },
    expect: (actual) => ({
      pass: actual === true,
      actual: actual ? "Edit link present" : "Edit link MISSING",
    }),
  },
  {
    name: "Overlay icon renders beside the text",
    input: "set meta.url on the text shape",
    expected: "icon appears clear of the text, vertically centred on it",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openCanvas(ctx);
      const shape = await createTextShapeViaToolbar(ctx, "linked note");
      await setLinkOnShape(ctx, shape.id, "https://example.com");
      await client.waitFor(`return document.querySelectorAll(${json(ICON)}).length > 0;`, {
        label: "icon rendered", timeout: 10000,
      });
      return client.evaluate(`const b = document.querySelector(${json(ICON)}).getBoundingClientRect();
        const s = document.querySelector('.tl-shape[data-shape-type="text"]').getBoundingClientRect();
        return { count: document.querySelectorAll(${json(ICON)}).length,
          clearOfText: b.left >= s.right - 1,
          centred: Math.abs((b.top + b.bottom) / 2 - (s.top + s.bottom) / 2) <= 3 };`);
    },
    expect: (actual) => ({
      pass: actual.count >= 1 && actual.clearOfText && actual.centred,
      actual: `${actual.count} icon(s), clearOfText=${actual.clearOfText}, centred=${actual.centred}`,
    }),
  },
  {
    name: "Click opens the page, Cmd+click opens a new tab",
    input: "click the link icon, then Cmd+click it",
    expected: "sidebar leaf, then a new root tab — matching discourse-node gestures",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openCanvas(ctx);
      const shape = await createTextShapeViaToolbar(ctx, "linked note");
      const path = await client.evaluate(`return app.vault.getMarkdownFiles()
        .find((f) => !f.path.startsWith("_verify/") && !f.path.startsWith("Discourse Canvas/"))?.path ?? null;`);
      const url = await client.evaluate(`return "obsidian://open?vault=" + encodeURIComponent(app.vault.getName())
        + "&file=" + encodeURIComponent(${json(path)});`);
      await setLinkOnShape(ctx, shape.id, url);
      await client.waitFor(`return !!document.querySelector(${json(ICON)});`, { label: "icon" });

      await client.evaluate(`document.querySelector(${json(ICON)}).click(); return true;`);
      await client.waitFor(`let hit = false;
        app.workspace.iterateAllLeaves((l) => { if (l.view && l.view.file && l.view.file.path === ${json(path)}) hit = true; });
        return hit;`, { label: "plain click opened the page", timeout: 8000 });

      const before = await client.evaluate(`let n = 0; app.workspace.iterateRootLeaves(() => { n++; }); return n;`);

