import { openCanvas, zoomToFit, selectNode, menuState, NODE_SEL } from "./lib.mjs";

const CANVASES = [
  "Discourse Canvas/ENG-2107 sync test.md",
  "Discourse Canvas/Canvas-2026-07-28-2210.md",
  "Discourse Canvas/Canvas-2026-07-28-2208.md",
];

export default CANVASES.map((path) => ({
  name: `probe ${path}`,
  input: path,
  expected: "inventory",
  run: async (ctx) => {
    await openCanvas(ctx, path);
    await zoomToFit(ctx);
    const n = await ctx.client.evaluate(`return document.querySelectorAll(${ctx.json(NODE_SEL)}).length;`);
    const out = [];
    for (let i = 0; i < Math.min(n, 6); i++) {
      await selectNode(ctx, i);
      await new Promise((r) => setTimeout(r, 1200));
      out.push({ i, ...(await menuState(ctx)) });
    }
    return { n, out };
  },
  expect: (a) => ({ pass: true, actual: JSON.stringify(a) }),
}));

