export const getNodeInstanceIdForFile = async (
  plugin: DiscourseGraphPlugin,
  file: TFile,
): Promise<string | null> => {
  let frontmatter = plugin.app.metadataCache.getFileCache(file)?.frontmatter as
    | Record<string, unknown>
    | undefined;

  if (!frontmatter?.nodeTypeId) {
    frontmatter =
      (await waitForDiscourseFrontmatter(plugin, file)) ?? undefined;
  }

  if (!frontmatter?.nodeTypeId) {
    return null;
  }
  return await ensureNodeInstanceId(plugin, file, frontmatter);
};

/**
 * Returns the node type id from a file's frontmatter (nodeTypeId).
 * Waits for metadata cache if not yet available (e.g. after file creation).
 */
 * are delegated to the default bookmark handler.
 */
export const handleExternalUrlContent = async ({
  editor,
  url,
  point,
  plugin,
  canvasFile,
  defaultHandlerOpts,
}: HandleExternalUrlOptions): Promise<void> => {
  const position =
    point ??
    (editor.inputs.shiftKey
      ? editor.inputs.currentPagePoint
      : editor.getViewportPageBounds().center);

  if (url.startsWith(OBSIDIAN_URL_PREFIX)) {
    const parsed = parseObsidianOpenUrl(url);
    if (!parsed) {
      new Notice("Invalid Obsidian link. Only discourse nodes can be dropped on the canvas.");
      return;
    }

    const file = resolveObsidianUrlToFile(plugin, parsed);
    if (!file) {
