export const addRelation = async (
  plugin: DiscourseGraphPlugin,
  params: AddRelationParams,
): Promise<AddRelationResult> => {
  const existingId = await relationExistsBetweenNodes({
    plugin,
    sourceNodeInstanceId: params.source,
