// ENG-1339: node card context menu is the default; legacy Relations overlay and admin flag are gone.
import { VIEW, NODE_SEL, ADD, REMOVE, clickAt, selectNode, menuState, arrowCount } from "./lib.mjs";

const PLUGIN = `app.plugins.plugins["@discourse-graph/obsidian"]`;
const shared = {}; // canvasPath, pair, relationsBackup — built once, reused by later scenarios

// tldraw's EditorContext value, found by walking the React fiber up from the canvas.
const EDITOR = `(() => {
  const el = document.querySelector(".tl-container");
  const key = Object.keys(el).find((k) => k.startsWith("__reactFiber$"));
  for (let f = el[key]; f; f = f.return) {
    const v = f.memoizedProps?.value;
    if (v && typeof v.putExternalContent === "function") return v;
  }
  return null;
})()`;

// First stored relation whose endpoints are both local discourse-node files.
const findPair = ({ client }) =>
  client.evaluate(`return (async () => {
    const data = JSON.parse(await app.vault.adapter.read("relations.json"));
    const byId = new Map();
    for (const f of app.vault.getMarkdownFiles()) {
      const fm = app.metadataCache.getFileCache(f)?.frontmatter;
      if (fm?.nodeInstanceId && fm?.nodeTypeId && !f.path.startsWith("_verify/")) byId.set(fm.nodeInstanceId, f.path);
    }
    const s = ${PLUGIN}.settings;
    const types = new Set(s.relationTypes.map((t) => t.id));
    for (const r of data.relations) {
      if (r.tentative || !types.has(r.type)) continue;
      const src = byId.get(r.source), dst = byId.get(r.destination);
      if (src && dst && src !== dst) return { id: r.id, src, dst };
    }
    return null;
  })();`);

const buildCanvas = async (ctx) => {
  const { client, json, vault } = ctx;
  shared.relationsBackup = await client.evaluate(`return app.vault.adapter.read("relations.json");`);
  shared.pair = await findPair(ctx);
  if (!shared.pair) throw new Error("no local relation pair in relations.json");
  await client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse();
    return app.commands.executeCommandById(${json(`${vault.pluginId}:create-discourse-graph-canvas`)});`);
  await client.waitFor(`return !!document.querySelector(".tl-canvas") && !!${VIEW}?.file;`, { label: "canvas", timeout: 15000 });
  shared.canvasPath = await client.evaluate(`return ${VIEW}.file.path;`);
  await new Promise((r) => setTimeout(r, 800));
  // Same path a drag from the file explorer takes: the plugin's url external-content handler.
  await client.evaluate(`const ed = ${EDITOR};
    const url = "obsidian://open?vault=" + encodeURIComponent(app.vault.getName()) + "&file=" + encodeURIComponent(${json(shared.pair.src)});
    ed.putExternalContent({ type: "url", url, point: ed.getViewportPageBounds().center });
    return true;`);
  await client.waitFor(`return document.querySelectorAll(${json(NODE_SEL)}).length === 1;`, { label: "source card", timeout: 10000 });
  await new Promise((r) => setTimeout(r, 800));
};

const reopenCanvas = async ({ client, json }) => {
  await client.evaluate(`return (async () => {
    app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse();
    const open = app.workspace.getLeavesOfType("tldraw-dg-preview").find((l) => l.view.file?.path === ${json(shared.canvasPath)});
    const leaf = open ?? app.workspace.getLeaf("tab");
    if (!open) await leaf.setViewState({ type: "tldraw-dg-preview", state: { file: ${json(shared.canvasPath)} }, active: true });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    return true;
  })();`);
  await client.waitFor(`return !!document.querySelector(${json(NODE_SEL)});`, { label: "canvas reopened", timeout: 15000 });
  await new Promise((r) => setTimeout(r, 600));
};

const selectSourceAndWait = async (ctx) => {
  await ctx.client.evaluate(`const ed = ${EDITOR}; ed.setCurrentTool("select"); ed.selectNone(); return true;`);
  await selectNode(ctx, 0);
  await ctx.client.waitFor(
    `return document.querySelectorAll(${ctx.json(`${ADD}, ${REMOVE}`)}).length > 0;`,
    { label: "relation rows loaded", timeout: 10000 },
  );
};

export default [
  {
    name: "Bundle ships without the flag",
    input: "read the vault plugin main.js",
    expected: "menu class present; no flag key, no '(BETA) Discourse context' toggle",
    run: ({ client }) =>
      client.evaluate(`return app.vault.adapter.read(".obsidian/plugins/discourse-graphs/main.js").then((t) => ({
        menu: t.includes("dg-node-card-menu"), flag: t.includes("nodeCardContextMenuEnabled"),
        toggle: t.includes("(BETA) Discourse context") }));`),
    expect: (a) => ({ pass: a.menu && !a.flag && !a.toggle, actual: JSON.stringify(a) }),
  },
  {
    name: "Context tab is the default for a node card",
    input: "stale data.json flag = false; drop a related node onto a new canvas; select it",
    expected: "Context + Styling tabs, relation row with +, no floating 'Relations' button",
    setup: async ({ client }) => ({
      saved: await client.evaluate(`return ${PLUGIN}.settings.nodeCardContextMenuEnabled ?? null;`),
    }),
    run: async (ctx) => {
      await ctx.client.evaluate(`${PLUGIN}.settings.nodeCardContextMenuEnabled = false; return true;`);
      await buildCanvas(ctx);
      await selectSourceAndWait(ctx);
      return menuState(ctx);
    },
    expect: (a) => ({
      pass: a.tabs.join() === "Context,Styling" && a.legacy === 0 && a.add + a.remove >= 1,
      actual: `tabs=${a.tabs}, legacy=${a.legacy}, +=${a.add}, -=${a.remove}`,
    }),
    teardown: async ({ client, json }, { saved }) => {
      await client.evaluate(`const s = ${PLUGIN}.settings;
        if (${json(saved)} === null) delete s.nodeCardContextMenuEnabled; else s.nodeCardContextMenuEnabled = ${json(saved)};
        return true;`);
    },
  },
  {
    name: "+ shows the relation on the canvas",
    input: "click + on the relation row",
    expected: "target card created, one relation arrow, button flips to −",
    run: async (ctx) => {
      const { client, json } = ctx;
      await reopenCanvas(ctx);
      await selectSourceAndWait(ctx);
      await client.evaluate(`document.querySelector(${json(ADD)}).click(); return true;`);
      await client.waitFor(`return ${VIEW}.store.allRecords().some((r) => r.type === "discourse-relation");`, {
        label: "arrow created", timeout: 10000,
      });
      await new Promise((r) => setTimeout(r, 800));
      return {
        arrows: await arrowCount(ctx),
        cards: await client.evaluate(`return ${VIEW}.store.allRecords().filter((r) => r.type === "discourse-node").length;`),
        ...(await menuState(ctx)),
      };
    },
    expect: (a) => ({
      pass: a.arrows === 1 && a.cards === 2 && a.remove >= 1,
      actual: `arrows=${a.arrows}, cards=${a.cards}, -=${a.remove}`,
    }),
  },
  {
    name: "− hides the relation, keeps it stored",
    input: "reselect the source card; click − on the relation row",
    expected: "arrow removed from canvas; relation still in relations.json",
    run: async (ctx) => {
      const { client, json } = ctx;
      await reopenCanvas(ctx);
      await selectSourceAndWait(ctx);
      await client.evaluate(`document.querySelector(${json(REMOVE)}).click(); return true;`);
      await client.waitFor(`return !${VIEW}.store.allRecords().some((r) => r.type === "discourse-relation");`, {
        label: "arrow removed", timeout: 10000,
      });
      const stored = await client.evaluate(`return app.vault.adapter.read("relations.json")
        .then((t) => JSON.parse(t).relations.some((r) => r.id === ${json(shared.pair.id)}));`);
      return { arrows: await arrowCount(ctx), stored, ...(await menuState(ctx)) };
    },
    expect: (a) => ({
      pass: a.arrows === 0 && a.stored && a.add >= 1,
      actual: `arrows=${a.arrows}, stored=${a.stored}, +=${a.add}`,
    }),
  },
  {
    name: "Non-node selection keeps the stock style panel",
    input: "click empty canvas (select tool, nothing selected)",
    expected: "tldraw style panel, no Context/Styling tabs",
    run: async (ctx) => {
      await reopenCanvas(ctx);
      await ctx.client.evaluate(`const ed = ${EDITOR}; ed.setCurrentTool("select"); ed.selectNone(); return true;`);
      await new Promise((r) => setTimeout(r, 500));
      return menuState(ctx);
    },
    expect: (a) => ({ pass: a.stylePanel && a.tabs.length === 0, actual: `stylePanel=${a.stylePanel}, tabs=${a.tabs.length}` }),
  },
  {
    name: "Discourse node tool hides the style panel",
    input: "activate the discourse-node tool",
    expected: "no style panel beside the DiscourseToolPanel",
    run: async (ctx) => {
      await reopenCanvas(ctx);
      await ctx.client.evaluate(`${EDITOR}.setCurrentTool("discourse-node"); return true;`);
      await new Promise((r) => setTimeout(r, 500));
      return menuState(ctx);
    },
    expect: (a) => ({ pass: !a.stylePanel, actual: `stylePanel=${a.stylePanel}` }),
    teardown: async ({ client, json }) => {
      await client.evaluate(`return (async () => {
        const ed = ${EDITOR}; ed?.setCurrentTool("select");
        await app.vault.adapter.write("relations.json", ${json(shared.relationsBackup ?? "")} || await app.vault.adapter.read("relations.json"));
        app.workspace.getLeavesOfType("tldraw-dg-preview").forEach((l) => { if (l.view.file?.path === ${json(shared.canvasPath)}) l.detach(); });
        const f = app.vault.getAbstractFileByPath(${json(shared.canvasPath ?? "")});
        if (f) await app.vault.trash(f, true);
        return true;
      })();`);
    },
  },
];

