1	// Shared helpers for ENG-1339 scenarios. evaluate() bodies need an explicit return.
2	export const VIEW = `app.workspace.activeLeaf?.view`;
3	export const ROOT = `app.workspace.activeLeaf.view.containerEl`; // other sessions may leave canvas tabs open
4	export const NODE_SEL = '.tl-shape[data-shape-type="discourse-node"]';
5	export const ADD = 'button[title="Add this relation to canvas"]';
6	export const REMOVE = 'button[title="Remove this relation from canvas"]';
7	
8	export const openCanvas = async ({ client, json }, path) => {
9	  await client.evaluate(`return (async () => {
10	    app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse();
11	    const leaf = app.workspace.getLeaf("tab");
12	    await leaf.setViewState({ type: "tldraw-dg-preview", state: { file: ${json(path)} }, active: true });
13	    return true;
14	  })();`);
15	  await client.waitFor(`return !!${ROOT}.querySelector(".tl-canvas") && !!${ROOT}.querySelector(${json(NODE_SEL)});`, {
16	    label: "canvas with node cards mounted",
17	    timeout: 15000,
18	  });
19	  await new Promise((r) => setTimeout(r, 600));
20	};
21	
22	export const clickAt = async ({ client }, { x, y }) => {
23	  for (const type of ["mousePressed", "mouseReleased"]) {
24	    await client.send("Input.dispatchMouseEvent", {
25	      type, x, y, button: "left", clickCount: 1, buttons: type === "mousePressed" ? 1 : 0,
26	    });
27	  }
28	};
29	
30	export const zoomToFit = async ({ client }) => {
31	  await clickAt({ client }, await client.evaluate(`const r = ${ROOT}.querySelector(".tl-canvas").getBoundingClientRect();
32	    return { x: Math.round(r.left + 8), y: Math.round(r.bottom - 8) };`));
33	  await client.key({ key: "!", code: "Digit1", text: "!", modifiers: 8, windowsVirtualKeyCode: 49, nativeVirtualKeyCode: 49 });
34	  await new Promise((r) => setTimeout(r, 800));
35	};
36	
37	// Click the visible centre of the i-th node card that isn't covered by UI.
38	export const selectNode = async ({ client, json }, i) => {
39	  const pt = await client.evaluate(`const els = [...${ROOT}.querySelectorAll(${json(NODE_SEL)})];
40	    const el = els[${i}]; if (!el) return null;
41	    const r = el.getBoundingClientRect();
42	    return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + Math.min(r.height / 2, 14)) };`);
43	  if (!pt) return false;
44	  await clickAt({ client }, pt);
45	  await new Promise((r) => setTimeout(r, 500));
46	  return true;
47	};
48	
49	export const menuState = ({ client, json }) =>
50	  client.evaluate(`const tabs = [...${ROOT}.querySelectorAll(".dg-node-card-menu button[aria-pressed]")]
51	      .map((b) => b.textContent.trim());
52	    const legacy = [...${ROOT}.querySelectorAll(".tl-container button")]
53	      .filter((b) => b.textContent.trim() === "Relations").length;
54	    return { tabs, legacy, stylePanel: !!${ROOT}.querySelector(".tlui-style-panel"),
55	      add: ${ROOT}.querySelectorAll(${json(ADD)}).length, remove: ${ROOT}.querySelectorAll(${json(REMOVE)}).length,
56	      text: ${ROOT}.querySelector(".dg-node-card-menu")?.innerText.slice(0, 200) ?? null };`);
57	
58	export const arrowCount = ({ client }) =>
59	  client.evaluate(`return ${VIEW}.store.allRecords().filter((r) => r.typeName === "shape" && r.type === "discourse-relation").length;`);

